1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
4	  rune: 25,
5	  moonstone: 25,
6	};
7	const MAIN_ITEM_BASE_PREMIUM_BY_TYPE: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	};
13	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
14	  ...MAIN_ITEM_BASE_PREMIUM_BY_TYPE,
15	  ...COMPONENT_BASE_PREMIUM_BY_TYPE,
16	};
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	const CURSED_SURCHARGE_RATE = 0.5;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
22	
23	type Item = {
24	  type: string;
25	  material?: string;
26	  enchantment?: number;
27	  cursed?: boolean;
28	};
29	
30	type Step = {
31	  op: string;
32	  items: Item[];
33	};
34	
35	type Scenario = {
36	  customer: { yearsWithMHPCO: number };
37	  steps: Step[];
38	};
39	
40	type QuoteResult = {
41	  premium: number;
42	};
43	
44	type ScenarioOutput = {
45	  results: QuoteResult[];
46	};
47	
48	const isComponent = (item: Item): boolean =>
49	  item.type in COMPONENT_BASE_PREMIUM_BY_TYPE;
50	
51	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
52	  sameTypeItems.length === COMPONENT_BLOCK_SIZE &&
53	  sameTypeItems.every(isComponent);
54	
55	const groupByType = (items: Item[]): Item[][] => {
56	  const groups = new Map<string, Item[]>();
57	  for (const item of items) {
58	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
59	  }
60	  return [...groups.values()];
61	};
62	
63	const basePremiumForItem = (item: Item): number =>
64	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
65	
66	const basePremiumForGroup = (sameTypeItems: Item[]): number => {
67	  if (isComponentBlock(sameTypeItems)) return COMPONENT_BLOCK_BASE_PREMIUM;
68	  return sameTypeItems.reduce(
69	    (total, item) => total + basePremiumForItem(item),
70	    0,
71	  );
72	};
73	
74	const basePremiumForItems = (items: Item[]): number =>
75	  groupByType(items).reduce(
76	    (total, group) => total + basePremiumForGroup(group),
77	    0,
78	  );
79	
80	const cursedSurcharge = (item: Item): number =>
81	  item.cursed ? basePremiumForItem(item) * CURSED_SURCHARGE_RATE : 0;
82	
83	const hasHighEnchantment = (item: Item): boolean =>
84	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
85	
86	const highEnchantmentSurcharge = (item: Item): number =>
87	  hasHighEnchantment(item)
88	    ? basePremiumForItem(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
89	    : 0;
90	
91	const totalItemSurcharges = (items: Item[]): number =>
92	  items.reduce(
93	    (total, item) =>
94	      total + cursedSurcharge(item) + highEnchantmentSurcharge(item),
95	    0,
96	  );
97	
98	const premiumBeforeProcessingFee = (items: Item[]): number => {
99	  const basePremium = basePremiumForItems(items);
100	  return (
101	    basePremium +
102	    totalItemSurcharges(items) +
103	    basePremium * FIRST_INSURANCE_SURCHARGE_RATE
104	  );
105	};
106	
107	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
108	  results: scenario.steps.map((step) => ({
109	    premium: Math.ceil(premiumBeforeProcessingFee(step.items) + PROCESSING_FEE),
110	  })),
111	});
